                nested: { secret: 'hidden' },
                query: 'Codex schema',
            },
            id: 'tool-1',
            result: {
                content: [{ type: 'text', text: 'Found result' }],
                structuredContent: { metadata: { source: 'hidden' }, resultCount: 1 },
            },
            server: 'docs',
            tool: 'search',
            type: 'mcpToolCall',
